python - <<'EOF'
import zipfile, re
from xml.etree import ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def col_idx(ref):
    letters = re.match(r'[A-Z]+', ref).group(0)
    n = 0
    for ch in letters:
        n = n*26 + (ord(ch)-64)
    return n

rows = {}
for row in root.iter(M+'row'):
    rnum = int(row.get('r'))
    for c in row.iter(M+'c'):
        ref = c.get('r'); t = c.get('t', 'n')
        v = c.find(M+'v'); is_ = c.find(M+'is')
        if t == 'inlineStr' and is_ is not None:
            val = ''.join(x.text or '' for x in is_.iter(M+'t'))
        elif v is not None:
            val = v.text
        else:
            val = ''
        rows.setdefault(rnum, {})[col_idx(ref)] = val

for rnum in sorted(rows):
    line = [f"R{rnum}"] + [f"{rows[rnum].get(ci,'')}" for ci in sorted(rows[rnum])]
    print(' | '.join(line))
